#include <iostream>
#include <vector>
#include <unordered_set>

using namespace std;

bool vectorsEqual(const long a[5], const long b[5]) {
    for (int i = 0; i < 5; i++) {
        if (a[i] != b[i]) return false;
    }
    return true;
}

bool vectorsDotProduct(const long a[5], const long b[5]) {
    long long sum = 0;
    for (int i = 0; i < 5; i++) {
        sum += (long long)a[i] * b[i];
    }
    return sum > 0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int nPoints;
    cin >> nPoints;
    if (nPoints <= 11) {
        vector<array<long, 5>> pointsData(nPoints);
        for (int i = 0; i < nPoints; i++) {
            for (int j = 0; j < 5; j++) {
                cin >> pointsData[i][j];
            }
        }
        vector<vector<array<long, 5>>> vectorsData(nPoints, vector<array<long, 5>>(nPoints));
        for (int i = 0; i < nPoints; i++) {
            for (int j = 0; j < nPoints; j++) {
                for (int k = 0; k < 5; k++) {
                    vectorsData[i][j][k] = pointsData[j][k] - pointsData[i][k];
                }
            }
        }
        unordered_set<int> affectedIndices;
        for (int i = 0; i < nPoints; i++) {
            bool isAffected = false;
            for (int j = 0; j < nPoints; j++) {
                for (int k = 0; k < nPoints; k++) {
                    if (!vectorsEqual(vectorsData[i][j].data(), vectorsData[i][k].data()) && vectorsDotProduct(vectorsData[i][j].data(), vectorsData[i][k].data())) {
                        affectedIndices.insert(i + 1);
                        isAffected = true;
                        break;
                    }
                }
                if (isAffected) break;
            }
        }
        cout << nPoints - (int)affectedIndices.size() << "\n";
        for (int i = 1; i <= nPoints; i++) {
            if (affectedIndices.find(i) == affectedIndices.end()) {
                cout << i << "\n";
            }
        }
    } else {
        cout << 0 << "\n";
    }
    return 0;
}
